import paramiko
client = paramiko.SSHClient()
client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
client.connect("46.202.154.25", 22, "root", "2N00py123+++")
# Add /ws location to arelorian.de config
ws_config = """
    location /ws {
        proxy_pass http://127.0.0.1:3000;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
    location /api {
        proxy_pass http://127.0.0.1:3000;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
    }
"""
# Backup and update config
stdin, stdout, stderr = client.exec_command("cp /etc/nginx/sites-enabled/arelorian.de /etc/nginx/sites-enabled/arelorian.de.backup")
# Add locations before the closing }
stdin, stdout, stderr = client.exec_command("sed -i 's|location /assets/ { expires 1y; add_header Cache-Control \"public\"; }|location /assets/ { expires 1y; add_header Cache-Control \"public\"; }\\n\\n    location /ws {\\n        proxy_pass http://127.0.0.1:3000;\\n        proxy_http_version 1.1;\\n        proxy_set_header Upgrade $http_upgrade;\\n        proxy_set_header Connection \"upgrade\";\\n        proxy_set_header Host $host;\\n        proxy_set_header X-Real-IP $remote_addr;\\n        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;\\n        proxy_set_header X-Forwarded-Proto $scheme;\\n    }\\n\\n    location /api {\\n        proxy_pass http://127.0.0.1:3000;\\n        proxy_set_header Host $host;\\n        proxy_set_header X-Real-IP $remote_addr;\\n        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;\\n        proxy_set_header X-Forwarded-Proto $scheme;\\n    }|' /etc/nginx/sites-enabled/arelorian.de")
print("Added /ws and /api")
# Reload nginx
stdin, stdout, stderr = client.exec_command("nginx -t && nginx -s reload 2>&1")
print("Nginx:", stdout.read().decode())
client.close()
EOF
